Phase.kernel_code:
pub enum Phase {
    /// Waiting for a request (relay low).
    Idle,
    /// The relay is high until `until`.
    Pulse { until: u64 },
    /// The relay is low; the next pulse can start at `until`.
    Pause { until: u64 },
}

