start.kernel_code:
fn start(now: u64) -> (Vrata, Act) {
    let until = now.saturating_add(PULSE_MS);
    (Vrata { phase: Phase::Pulse { until }, pending: false }, Act { relay: Some(true), timer_at: Some(until) })
}

Act.kernel_code:
pub struct Act {
    pub relay: Option<bool>,
    pub timer_at: Option<u64>,
}

step.kernel_code:
pub fn step(v: &Vrata, ev: Event, now: u64) -> (Vrata, Act) {
    match (v.phase, ev) {
        (Phase::Idle, Event::Request) => start(now),
        (Phase::Idle, Event::Timer) => (*v, NONE),
        (Phase::Pulse { until }, Event::Request) => {
            (Vrata { phase: Phase::Pulse { until }, pending: true }, NONE)
        }
        (Phase::Pulse { until }, Event::Timer) => {
            if now < until {
                (*v, NONE)
            } else {
                let next = now.saturating_add(PAUSE_MS);
                (
                    Vrata { phase: Phase::Pause { until: next }, pending: v.pending },
                    Act { relay: Some(false), timer_at: Some(next) },
                )
            }
        }
        (Phase::Pause { until }, Event::Request) => {
            (Vrata { phase: Phase::Pause { until }, pending: true }, NONE)
        }
        (Phase::Pause { until }, Event::Timer) => {
            if now < until {
                (*v, NONE)
            } else if v.pending {
                start(now)
            } else {
                (Vrata { phase: Phase::Idle, pending: false }, NONE)
            }
        }
    }
}

